const app=document.getElementById('app');
let catalog=[];
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const key=id=>`animeshelf:progress:${id}`;
const progress=id=>{try{return JSON.parse(localStorage.getItem(key(id)))}catch{return null}};
const save=(id,data)=>{try{localStorage.setItem(key(id),JSON.stringify({...data,updated:Date.now()}))}catch{}};
const time=seconds=>{let n=Math.max(0,Math.floor(Number(seconds)||0)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return (h?`${h}:${String(m).padStart(2,'0')}`:String(m))+`:${String(s).padStart(2,'0')}`};
const url=(id,s,e)=>`#/watch/${encodeURIComponent(id)}/${s}/${e}`;
const titleUrl=id=>`#/title/${encodeURIComponent(id)}`;
const item=id=>catalog.find(x=>x.id===id);
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('');
let activeVideo=null;
function storeCurrent(){if(activeVideo){activeVideo.save();activeVideo=null}}
function currentRoute(){const parts=location.hash.slice(2).split('/').map(decodeURIComponent);return {view:parts[0]||'home',id:parts[1],season:Number(parts[2]),episode:Number(parts[3])}}
function render(){storeCurrent();const r=currentRoute();document.getElementById('navAll').classList.toggle('active',r.view!=='continue');document.getElementById('navContinue').classList.toggle('active',r.view==='continue');if(r.view==='title')renderTitle(item(r.id));else if(r.view==='watch')renderCustomWatch(item(r.id),r);else renderHome(r.view==='continue');window.scrollTo(0,0)}
function card(anime){const p=progress(anime.id);return `<a class="card" href="${titleUrl(anime.id)}"><div class="card-art"><span class="card-grid"></span><span class="card-initial">${esc(initials(anime.title))}</span><span class="card-number">${String(catalog.indexOf(anime)+1).padStart(2,'0')}</span></div><div class="card-copy"><h3>${esc(anime.title)}</h3><p>${anime.seasons.length} ${anime.seasons.length===1?'сезон':'сезонов'} <span>·</span> ${anime.episodeCount} серий</p>${p?`<span class="card-progress">▶ Сезон ${p.season}, серия ${p.episode} · ${time(p.time)}</span>`:''}</div></a>`}
function renderHome(continued){app.innerHTML=`<section class="intro shell"><div class="breadcrumb">БИБЛИОТЕКА <span>/</span> ${continued?'ПРОДОЛЖИТЬ':'КАТАЛОГ'}</div><div class="intro-line"><div><span class="section-kicker">ВАША КОЛЛЕКЦИЯ</span><h1>${continued?'Продолжить просмотр':'Все аниме'}<span class="title-period">.</span></h1><p>${continued?'Ваши последние серии и сохранённые таймкоды':'Тайтлы автоматически появляются здесь из папок в dist'}</p></div><div class="library-stat"><strong>${catalog.length}</strong><span>ТАЙТЛОВ В БИБЛИОТЕКЕ</span></div></div></section><section class="shell library"><div class="toolbar"><div class="toolbar-title"><h2>${continued?'История просмотра':'Каталог'}</h2><span id="resultCount"></span></div><div class="tools">${continued?'':`<label class="search"><span>⌕</span><input id="search" type="search" placeholder="Поиск по названию" autocomplete="off"></label><select id="sort" aria-label="Сортировка"><option value="name">По названию</option><option value="seasons">По сезонам</option><option value="episodes">По сериям</option></select>`}</div></div><div class="card-grid-list" id="cards"></div></section>`;const redraw=()=>{let items=continued?catalog.filter(x=>progress(x.id)).sort((a,b)=>(progress(b.id)?.updated||0)-(progress(a.id)?.updated||0)):catalog.filter(x=>x.title.toLocaleLowerCase('ru').includes((document.getElementById('search')?.value||'').toLocaleLowerCase('ru')));if(!continued){const sort=document.getElementById('sort')?.value;if(sort==='seasons')items.sort((a,b)=>b.seasons.length-a.seasons.length);else if(sort==='episodes')items.sort((a,b)=>b.episodeCount-a.episodeCount);else items.sort((a,b)=>a.title.localeCompare(b.title,'ru'))}document.getElementById('resultCount').textContent=items.length;document.getElementById('cards').innerHTML=items.length?items.map(card).join(''):`<div class="empty"><div class="empty-icon">◇</div><h3>${continued?'Пока нет просмотренных серий':catalog.length?'Ничего не найдено':'Каталог пока пуст'}</h3><p>${continued?'Начните просмотр любого тайтла.':catalog.length?'Попробуйте другое название.':'Создайте папку dist/Название аниме/season 1 и добавьте видеофайлы серий.'}</p></div>`};redraw();document.getElementById('search')?.addEventListener('input',redraw);document.getElementById('sort')?.addEventListener('change',redraw)}
function renderTitle(anime){if(!anime){location.hash='#/';return}let p=progress(anime.id);const first=anime.seasons[0].episodes[0];app.innerHTML=`<section class="shell detail"><a class="back" href="#/">← &nbsp;Все аниме</a><div class="detail-main"><div class="detail-symbol"><span>${esc(initials(anime.title))}</span><i>◈</i></div><div class="detail-copy"><span class="section-kicker">ИЗ ВАШЕЙ БИБЛИОТЕКИ</span><h1>${esc(anime.title)}</h1><div class="detail-meta"><span>${anime.seasons.length} ${anime.seasons.length===1?'сезон':'сезонов'}</span><span>${anime.episodeCount} серий</span><span>Локальное видео</span></div><p>Выберите сезон и серию для просмотра. Прогресс и озвучка сохраняются автоматически в этом браузере.</p><a class="primary-button" href="${url(anime.id,p?.season||anime.seasons[0].number,p?.episode||first.number)}">▶ &nbsp;${p?'Продолжить с '+time(p.time):'Начать просмотр'}</a></div></div><div class="detail-episodes"><div class="subhead"><div><span class="section-kicker">СПИСОК СЕРИЙ</span><h2>Серии</h2></div><label class="select-label">СЕЗОН <select id="seasonPicker">${anime.seasons.map(s=>`<option value="${s.number}">Сезон ${s.number}</option>`).join('')}</select></label></div><div class="episode-grid" id="episodeGrid"></div></div></section>`;const picker=document.getElementById('seasonPicker');picker.value=String(p?.season||anime.seasons[0].number);const draw=()=>{let season=anime.seasons.find(s=>s.number===Number(picker.value))||anime.seasons[0];document.getElementById('episodeGrid').innerHTML=season.episodes.map(ep=>`<a class="episode-card" href="${url(anime.id,season.number,ep.number)}"><span class="episode-index">${String(ep.number).padStart(2,'0')}</span><span class="episode-text"><strong>${esc(ep.title)}</strong><small>${ep.dubs.length} ${ep.dubs.length===1?'вариант':'варианта'} озвучки</small></span><span class="episode-play">▶</span></a>`).join('')};picker.onchange=draw;draw()}
async function refresh(){try{const response=await fetch('/api/catalog',{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);catalog=await response.json();render()}catch(error){app.innerHTML=`<div class="shell empty"><div class="empty-icon">!</div><h2>Каталог недоступен</h2><p>Запустите сайт командой <code>python3 server.py</code> из корневой папки проекта.</p><small>${esc(error.message)}</small></div>`}}
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',storeCurrent);refresh();
